Here is the root cause:
The bug arises from the function_graph tracer not displaying the interrupt return marker for leaf entries, leading to an unbalanced interrupt marker where the interrupt is shown as entered but never exited. This occurs because the code responsible for printing the interrupt return marker was missing for leaf function entries.

Here is the patch:
 /* Case of a leaf function on its call entry */
 static enum print_line_t
 print_graph_entry_leaf(struct trace_iterator *iter,
 		struct ftrace_graph_ent_entry *entry,
 		struct ftrace_graph_ret_entry *ret_entry,
 		struct trace_seq *s, u32 flags)
 {
 	struct fgraph_data *data = iter->private;
 	struct trace_array *tr = iter->tr;
 	struct ftrace_graph_ret *graph_ret;
 	struct ftrace_graph_ent *call;
 	unsigned long long duration;
+	int cpu = iter->cpu;
 	int i;

 	graph_ret = &ret_entry->ret;
 	call = &entry->graph_ent;
 	duration = graph_ret->rettime - graph_ret->calltime;

 	if (data) {
 		struct fgraph_cpu_data *cpu_data;
-		int cpu = iter->cpu;

 		cpu_data = per_cpu_ptr(data->cpu_data, cpu);

 		/* If a graph tracer ignored set_graph_notrace */
 		if (call->depth < -1)
 			call->depth += FTRACE_NOTRACE_DEPTH;

 		/*
 		 * Comments display at + 1 to depth. Since
 		 * this is a leaf function, keep the comments
 		 * equal to this depth.
 		 */
 		cpu_data->depth = call->depth - 1;

 		/* No need to keep this function around for this depth */
 		if (call->depth < FTRACE_RETFUNC_DEPTH &&
 		    !WARN_ON_ONCE(call->depth < 0))
 			cpu_data->enter_funcs[call->depth] = 0;
 	}

 	/* Overhead and duration */
 	print_graph_duration(tr, duration, s, flags);

 	/* Function */
 	for (i = 0; i < call->depth * TRACE_GRAPH_INDENT; i++)
 		trace_seq_putc(s, ' ');

 	trace_seq_printf(s, "%ps();\n", (void *)call->func);

+	print_graph_irq(iter, graph_ret->func, TRACE_GRAPH_RET,
+			cpu, iter->ent->pid, flags);
+
 	return trace_handle_return(s);
 }



